//! Parity and regression tests for the rumik-oss TTS family.
//!
//! Pinned fixtures reside in `testdata/tts_rumik_oss/`, generated by
//! `tools/gen_rumik_oss_fixtures.py` against mlx-audio 0.5.7 commit
//! `e1b19b9054bf163f5d812221a54fcc346f1890e9` (mlx 0.32.3). The
//! generator runs the true reference module (its network Mimi singleton
//! patched for a tiny seeded 8-book codec and the tokenizer swapped for
//! a deterministic offline mock), so the traces carry the reference
//! round-robin assembler states, `audio_tokens_to_codes` outputs,
//! build_prompt strings, stop-predictor probabilities, the
//! `make_audio_logits_processor` masks, and greedy generate loops driven
//! by `mlx_audio.lm.generate.generate_step` end to end through the
//! reference `_decode_frames`.

use std::path::{Path, PathBuf};

use serde_json::Value;
use turbospark_model_io::safetensors::SafetensorsFile;

use super::{
    frames_to_codes, AudioVocab, GenerateParams, Model, StopReason, DEFAULT_CODEBOOK_SIZE,
    DEFAULT_FRAME_RATE_HZ, DEFAULT_NUM_QUANTIZERS, DEFAULT_SAMPLE_RATE, DEFAULT_SPEAKERS,
};
use crate::codec::mimi::{Mimi, MimiConfig};
use crate::tts::sampling;

fn testdata(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("testdata/tts_rumik_oss")
        .join(name)
}

fn read_json(path: &Path) -> Value {
    let text = std::fs::read_to_string(path).expect("fixture json");
    serde_json::from_str(&text).expect("fixture json")
}

fn i32_vec(value: &Value) -> Vec<i32> {
    value
        .as_array()
        .expect("ids")
        .iter()
        .map(|v| v.as_i64().expect("id") as i32)
        .collect()
}

fn i32_rows(value: &Value) -> Vec<Vec<i32>> {
    value
        .as_array()
        .expect("rows")
        .iter()
        .map(i32_vec)
        .collect()
}

fn f32_vec(value: &Value) -> Vec<f32> {
    value
        .as_array()
        .expect("values")
        .iter()
        .map(|v| v.as_f64().expect("value") as f32)
        .collect()
}

/// Filtered log-prob entries use null for the reference's negative
/// infinities (strict JSON cannot carry them).
fn f32_vec_masked(value: &Value) -> Vec<f32> {
    value
        .as_array()
        .expect("values")
        .iter()
        .map(|v| {
            if v.is_null() {
                f32::NEG_INFINITY
            } else {
                v.as_f64().expect("value") as f32
            }
        })
        .collect()
}

fn max_abs_diff(a: &[f32], b: &[f32]) -> f32 {
    assert_eq!(
        a.len(),
        b.len(),
        "length mismatch: {} vs {}",
        a.len(),
        b.len()
    );
    a.iter()
        .zip(b)
        .map(|(x, y)| (x - y).abs())
        .fold(0.0f32, f32::max)
}

/// Measured maximum differences when the gates were frozen; assertions
/// use these values, not re-measured ones. The waveform gate sits above
/// the measured Mimi decode diff (conv and FFT accumulation order); the
/// probability and sampler gates sit above the f32 sigmoid and
/// log-softmax reduction noise.
const WAVEFORM_TOLERANCE: f32 = 2e-6;
const PROBABILITY_TOLERANCE: f32 = 1e-6;
const SAMPLING_TOLERANCE: f32 = 2e-6;

fn open_model(name: &str) -> Model {
    Model::open(&testdata(name)).expect("family model loads")
}

fn open_mimi(case: &str) -> Mimi {
    let config_value = read_json(&testdata(case).join("codec_config.json"));
    let config = MimiConfig::from_json(&config_value).expect("mimi config");
    let file =
        SafetensorsFile::open(&testdata(case).join("codec.safetensors")).expect("weights open");
    Mimi::load(config, &file).expect("tiny mimi loads")
}

/// The reference voice error quotes the name with Python repr (single
/// quotes) while Rust Debug uses double quotes; compare quote-free.
fn quote_insensitive(text: &str) -> String {
    text.replace('"', "'")
}

#[test]
fn round_robin_assembler_matches_the_reference_states() {
    let traces = read_json(&testdata("decode/traces.json"));
    let model = open_model("decode");
    for case in traces["assembler"].as_array().expect("cases") {
        let tokens = i32_vec(&case["tokens"]);
        let mut frame = Vec::new();
        let mut frames = Vec::new();
        for (entry, &token) in case["steps"].as_array().expect("steps").iter().zip(&tokens) {
            if let Some(done) = model.audio.push_audio_token(token, &mut frame) {
                frames.push(done);
            }
            assert_eq!(
                frame,
                i32_vec(&entry["frame"]),
                "case {} frame after token {}",
                case["name"],
                token
            );
        }
        assert_eq!(
            frames,
            i32_rows(&case["frames"]),
            "case {} completed frames",
            case["name"]
        );
        assert_eq!(
            model.audio_tokens_to_codes(&tokens).unwrap(),
            i32_rows(&case["codes"]),
            "case {} codes",
            case["name"]
        );
    }
}

#[test]
fn audio_tokens_to_codes_refuses_a_frameless_input() {
    let traces = read_json(&testdata("decode/traces.json"));
    let model = open_model("decode");
    let error = model.audio_tokens_to_codes(&[30, 31, 32]).unwrap_err();
    assert!(
        error
            .to_string()
            .contains(traces["no_frame_error"].as_str().expect("message")),
        "{error}"
    );
}

#[test]
fn config_derives_the_last_unit_id_like_post_init() {
    let traces = read_json(&testdata("decode/traces.json"));
    // The reference __post_init__ derivation at the real 2048 x 8 shape.
    let config = serde_json::json!({
        "model_type": "rumik_oss",
        "hidden_size": 32,
        "num_hidden_layers": 1,
        "intermediate_size": 32,
        "num_attention_heads": 4,
        "num_key_value_heads": 2,
        "vocab_size": 8,
        "num_quantizers": 8,
        "codebook_size": 2048,
        "first_unit_id": 24,
        "audio_end_token_id": 16408,
    });
    let parsed = super::ModelConfig::from_json(&config).unwrap();
    let vocab = AudioVocab::from_config(&parsed).unwrap();
    assert_eq!(
        vocab.last_unit_id,
        traces["derived_last_unit_id"].as_i64().expect("derived") as i32
    );
    assert_eq!(vocab.first_unit_id, 24);
    // A checkpoint that omits the range or the stop id is refused, not
    // guessed (the reference would int(None)).
    let missing = serde_json::json!({
        "model_type": "rumik_oss",
        "hidden_size": 32,
        "num_hidden_layers": 1,
        "intermediate_size": 32,
        "num_attention_heads": 4,
        "num_key_value_heads": 2,
        "vocab_size": 8,
    });
    let parsed = super::ModelConfig::from_json(&missing).unwrap();
    assert!(AudioVocab::from_config(&parsed).is_err());
}

#[test]
fn decode_frames_match_the_tiny_mimi() {
    let traces = read_json(&testdata("decode/traces.json"));
    let codes = i32_rows(&traces["assembler"][0]["codes"]);
    let mimi = open_mimi("decode");
    let got = super::decode_frames(&mimi, &codes).unwrap();
    let want = f32_vec(&traces["waveform"]);
    assert_eq!(got.len(), want.len());
    assert_eq!(traces["waveform_sample_rate"].as_u64(), Some(24000));
    let diff = max_abs_diff(&got, &want);
    assert!(diff <= WAVEFORM_TOLERANCE, "decode waveform diff {diff}");
    // The level-major layout: frames_to_codes transposes [T][Q] to [Q][T].
    let frames = i32_rows(&traces["assembler"][0]["frames"]);
    assert_eq!(frames_to_codes(&frames).unwrap(), codes);
}

fn greedy_params(traces: &Value) -> GenerateParams {
    GenerateParams {
        temperature: 0.0,
        top_p: 1.0,
        top_k: 30,
        max_tokens: traces["max_tokens"].as_u64().expect("max_tokens") as usize,
        min_tokens: traces["min_tokens"].as_u64().expect("min_tokens") as usize,
    }
}

#[test]
fn greedy_generation_forces_audio_end_through_the_stop_predictor() {
    let traces = read_json(&testdata("generate_forced/traces.json"));
    let mut model = open_model("generate_forced");
    let mimi = open_mimi("generate_forced");
    let prompt = i32_vec(&traces["prompt_ids"]);
    let got = model
        .generate_from_prompt(&mimi, &prompt, &greedy_params(&traces), 0)
        .expect("forced run");
    assert_eq!(got.tokens, i32_vec(&traces["generated"]));
    assert_eq!(got.frames, i32_rows(&traces["frames"]));
    assert_eq!(got.codes, i32_rows(&traces["codes"]));
    assert_eq!(got.stopped_by, StopReason::AudioEnd);
    // The forced run stops on the stop-predictor-forced </audio> right
    // after min_tokens generated tokens.
    assert_eq!(
        got.tokens.len(),
        traces["min_tokens"].as_u64().unwrap() as usize + 1
    );
    assert_eq!(*got.tokens.last().unwrap(), model.audio.audio_end_token_id);
    let diff = max_abs_diff(&got.samples, &f32_vec(&traces["waveform"]));
    assert!(diff <= WAVEFORM_TOLERANCE, "forced waveform diff {diff}");
}

#[test]
fn greedy_generation_stops_at_max_tokens_without_the_stop_predictor() {
    let traces = read_json(&testdata("generate_length/traces.json"));
    let mut model = open_model("generate_length");
    let mimi = open_mimi("generate_length");
    let prompt = i32_vec(&traces["prompt_ids"]);
    let got = model
        .generate_from_prompt(&mimi, &prompt, &greedy_params(&traces), 0)
        .expect("length run");
    assert_eq!(got.tokens, i32_vec(&traces["generated"]));
    assert_eq!(got.frames, i32_rows(&traces["frames"]));
    assert_eq!(got.codes, i32_rows(&traces["codes"]));
    assert_eq!(got.stopped_by, StopReason::MaxTokens);
    let diff = max_abs_diff(&got.samples, &f32_vec(&traces["waveform"]));
    assert!(diff <= WAVEFORM_TOLERANCE, "length waveform diff {diff}");
}

#[test]
fn generate_refuses_an_empty_prompt() {
    let mut model = open_model("generate_forced");
    let mimi = open_mimi("decode");
    let error = model
        .generate_from_prompt(&mimi, &[], &GenerateParams::default(), 0)
        .unwrap_err();
    assert!(error.to_string().contains("empty prompt"), "{error}");
}

#[test]
fn prompt_building_matches_the_reference() {
    let traces = read_json(&testdata("decode/traces.json"));
    let model = open_model("decode");
    for case in traces["prompts"].as_array().expect("prompts") {
        if let Some(expected) = case.get("error") {
            let error = model
                .resolve_voice(Some(case["voice"].as_str().expect("voice")))
                .unwrap_err();
            assert!(
                quote_insensitive(&error.to_string())
                    .contains(&quote_insensitive(expected.as_str().expect("message"))),
                "{error}"
            );
            continue;
        }
        let description = case
            .get("description")
            .and_then(Value::as_str)
            .or_else(|| case.get("instruct").and_then(Value::as_str));
        let got = model
            .build_prompt(
                case["text"].as_str().expect("text"),
                case.get("voice").and_then(Value::as_str),
                description,
            )
            .unwrap();
        assert_eq!(got, case["prompt"].as_str().expect("prompt"));
    }
}

#[test]
fn stop_probability_matches_the_reference_head() {
    let traces = read_json(&testdata("decode/traces.json"));
    let model = open_model("decode");
    for case in traces["stop_probability"].as_array().expect("rows") {
        let hidden = f32_vec(&case["hidden"]);
        let got = model.stop_probability(&hidden).unwrap();
        let want = case["probability"].as_f64().expect("probability") as f32;
        assert!(
            (got - want).abs() <= PROBABILITY_TOLERANCE,
            "{got} vs {want}"
        );
    }
}

#[test]
fn audio_logits_processor_matches_the_reference() {
    let traces = read_json(&testdata("sampling/traces.json"));
    let audio = AudioVocab {
        first_unit_id: traces["audio"]["first_unit_id"].as_i64().expect("first") as i32,
        last_unit_id: traces["audio"]["last_unit_id"].as_i64().expect("last") as i32,
        audio_end_token_id: traces["audio"]["audio_end_token_id"].as_i64().expect("end") as i32,
        num_quantizers: 2,
    };
    for case in traces["cases"].as_array().expect("cases") {
        let logits = f32_vec(&case["logits"]);
        let processed = super::process_audio_logits(
            &logits,
            case["step"].as_u64().expect("step") as usize,
            case["min_tokens"].as_u64().expect("min_tokens") as usize,
            &audio,
            case["stop_probability"].as_f64().expect("stop") as f32,
        );
        let diff = max_abs_diff(&processed, &f32_vec_masked(&case["processed"]));
        assert!(
            diff <= SAMPLING_TOLERANCE,
            "case {} processed diff {diff}",
            case["name"]
        );
        let logprobs = sampling::log_softmax(&processed);
        let diff = max_abs_diff(&logprobs, &f32_vec_masked(&case["logprobs"]));
        assert!(
            diff <= SAMPLING_TOLERANCE,
            "case {} logprobs diff {diff}",
            case["name"]
        );
        assert_eq!(
            sampling::argmax(&logprobs),
            case["argmax"].as_u64().expect("argmax") as usize,
            "case {} argmax",
            case["name"]
        );
        let mut filtered = logprobs.clone();
        sampling::apply_top_p(&mut filtered, 0.9);
        let diff = max_abs_diff(&filtered, &f32_vec_masked(&case["top_p_logprobs"]));
        assert!(
            diff <= SAMPLING_TOLERANCE,
            "case {} top_p diff {diff}",
            case["name"]
        );
        let mut filtered = logprobs;
        sampling::apply_top_k(&mut filtered, 30).unwrap();
        let diff = max_abs_diff(&filtered, &f32_vec_masked(&case["top_k_logprobs"]));
        assert!(
            diff <= SAMPLING_TOLERANCE,
            "case {} top_k diff {diff}",
            case["name"]
        );
    }
}

#[test]
fn family_defaults_match_the_reference_dataclass() {
    assert_eq!(super::MIMI_REPO, "kyutai/moshiko-pytorch-bf16");
    assert_eq!(DEFAULT_NUM_QUANTIZERS, 8);
    assert_eq!(DEFAULT_CODEBOOK_SIZE, 2048);
    assert_eq!(DEFAULT_FRAME_RATE_HZ, 12.5);
    assert_eq!(DEFAULT_SAMPLE_RATE, 24000);
    assert_eq!(DEFAULT_SPEAKERS, ["Ira", "Aisha", "Siya", "Zoya"]);
    let config = serde_json::json!({
        "model_type": "rumik_oss",
        "hidden_size": 32,
        "num_hidden_layers": 1,
        "intermediate_size": 32,
        "num_attention_heads": 4,
        "num_key_value_heads": 2,
        "vocab_size": 8,
        "first_unit_id": 24,
        "audio_end_token_id": 7,
    });
    let parsed = super::ModelConfig::from_json(&config).unwrap();
    assert_eq!(parsed.num_quantizers, DEFAULT_NUM_QUANTIZERS);
    assert_eq!(parsed.codebook_size, DEFAULT_CODEBOOK_SIZE);
    assert_eq!(parsed.frame_rate_hz, DEFAULT_FRAME_RATE_HZ);
    assert_eq!(parsed.sample_rate, DEFAULT_SAMPLE_RATE);
    assert_eq!(
        parsed.speakers,
        DEFAULT_SPEAKERS
            .iter()
            .map(|s| s.to_string())
            .collect::<Vec<_>>()
    );
    // The loaded decode fixture model reads its config fields through.
    let model = open_model("decode");
    assert_eq!(model.sample_rate(), 24000);
    assert_eq!(model.frame_rate_hz(), 12.5);
}
